window.docContents[243].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/Image-of-GL_LPAR_V_RPAR_-in-End_LPAR_V_________n____RPAR_-spans-B/#Chapter5___Proposition5___19___1":{"contents":"Proposition 5.19.1. The image of GL(V) in \\operatorname{End}(V^{\\otimes n}) spans B.\n\nProof. Recall that B is spanned by the elements g^{\\otimes n}, g \\in \\operatorname{End} V. Denote the span of g^{\\otimes n}, g \\in GL(V), by B'. Let b \\in \\operatorname{End} V be any element.\n\nWe claim that B' contains b^{\\otimes n}. Indeed, for all values of t but finitely many, t \\cdot \\operatorname{Id} + b is invertible, so (t \\cdot \\operatorname{Id} + b)^{\\otimes n} belongs to B'. This implies that this is true for all t, in particular t = 0, since (t \\cdot \\operatorname{Id} + b)^{\\otimes n} is a polynomial of t. More precisely, if f is a linear function on \\operatorname{End}(V^{\\otimes n}) that vanishes on B' then f((t \\cdot \\operatorname{Id} + b)^{\\otimes n}) is a scalar-valued polynomial of t which vanishes for almost all t \\in k, hence is identically zero.\n\nThe rest follows from Lemma 5.18.3. \\square\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.19. Schur-Weyl duality for $GL(V)$\tImage of GL(V) in End(V^{⊗n}) spans B","header":"Image of GL(V) in End(V^{⊗n}) spans B","id":"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/Image-of-GL_LPAR_V_RPAR_-in-End_LPAR_V_________n____RPAR_-spans-B/#Chapter5___Proposition5___19___1"},"/5___-Representations-of-finite-groups___-Further-results/5___8___-Induced-representations/Transitivity-of-induction___-Ind_H___G-Ind_K___H-V-___-Ind_K___G-V/#Chapter5___Problem5___8___4":{"contents":"Problem 5.8.4. Check that if K \\subset H \\subset G are groups and if V is a representation of K, then \\operatorname{Ind}_H^G \\operatorname{Ind}_K^H V is isomorphic to \\operatorname{Ind}_K^G V.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.8. Induced representations\tTransitivity of induction: Ind_H^G Ind_K^H V ≅ Ind_K^G V","header":"Transitivity of induction: Ind_H^G Ind_K^H V ≅ Ind_K^G V","id":"/5___-Representations-of-finite-groups___-Further-results/5___8___-Induced-representations/Transitivity-of-induction___-Ind_H___G-Ind_K___H-V-___-Ind_K___G-V/#Chapter5___Problem5___8___4"}});
